//! Pure metainfo construction for locally created v1, v2, and hybrid torrents.
//!
//! The daemon owns filesystem traversal and streaming hashes. This module owns
//! canonical bencoding, file-tree and piece-layer construction, and the
//! shared request/result models for the native API and Web UI. Generated bytes
//! are always re-parsed by the caller with the normal bounded metainfo parser
//! before they are exported or used to seed.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use sha1::Digest as _;

use crate::error::{CoreError, Result};
use crate::hash::V2InfoHash;
use crate::meta::{MAX_PIECE_LENGTH, MAX_TORRENT_FILES, MAX_TORRENT_PIECES, V2_BLOCK_LENGTH};

/// Default piece length for a new torrent. It is a valid v1 and BEP 52 length.
pub const DEFAULT_CREATION_PIECE_LENGTH: u64 = 256 * 1024;

/// Output format for generated metainfo.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TorrentCreationFormat {
    #[default]
    V1,
    V2,
    Hybrid,
}

impl TorrentCreationFormat {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::V1 => "v1",
            Self::V2 => "v2",
            Self::Hybrid => "hybrid",
        }
    }

    pub fn includes_v1(self) -> bool {
        matches!(self, Self::V1 | Self::Hybrid)
    }

    pub fn includes_v2(self) -> bool {
        matches!(self, Self::V2 | Self::Hybrid)
    }
}

/// A local creation request. `source` is resolved and bounded by the daemon;
/// this value is only the transport shape shared with the API and Web UI.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TorrentCreationRequest {
    pub source: String,
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub format: TorrentCreationFormat,
    #[serde(default)]
    pub piece_length: Option<u64>,
    /// Ordered tracker tiers. An empty list inserts no tracker.
    #[serde(default)]
    pub tracker_tiers: Vec<Vec<String>>,
    /// Optional BEP 19 webseed URLs. An empty list inserts no webseed.
    #[serde(default)]
    pub webseeds: Vec<String>,
    #[serde(default)]
    pub private: bool,
    /// Register the created torrent and start seeding immediately.
    #[serde(default)]
    pub seed: bool,
}

/// One file in a generated torrent. `path` is the complete torrent-relative
/// path including the root name (`[name, ...]` for multi-file torrents).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CreationFile {
    pub path: Vec<String>,
    pub length: u64,
    /// BEP 52 file-tree pieces root. Required for every non-empty v2/hybrid
    /// file.
    pub pieces_root: Option<V2InfoHash>,
    /// BEP 52 piece hashes. Required only for files larger than the piece
    /// length. Empty for smaller files and v1-only files.
    pub piece_layer: Vec<V2InfoHash>,
}

/// Fully hashed input for the canonical metainfo writer.
#[derive(Debug, Clone)]
pub struct TorrentCreationSpec {
    pub name: String,
    pub piece_length: u64,
    pub format: TorrentCreationFormat,
    pub is_multi_file: bool,
    pub files: Vec<CreationFile>,
    /// SHA-1 piece hashes in torrent order. Required for v1/hybrid.
    pub v1_pieces: Vec<[u8; 20]>,
    pub tracker_tiers: Vec<Vec<String>>,
    pub webseeds: Vec<String>,
    pub private: bool,
}

/// API/UI-visible creation result.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TorrentCreationResult {
    pub name: String,
    pub format: TorrentCreationFormat,
    pub total_length: u64,
    pub piece_length: u64,
    pub piece_count: u64,
    pub file_count: usize,
    pub private: bool,
    /// Full v1/hybrid-primary and v2 locators, as applicable.
    pub torrent_keys: Vec<String>,
    pub tracker_tiers: Vec<Vec<String>>,
    pub webseeds: Vec<String>,
    /// Hex-encoded exact `.torrent` document. This is the export
    /// representation consumed by the Web UI download action.
    pub metainfo_hex: String,
    pub metainfo_bytes: usize,
    pub seeded: bool,
    pub seed_state: Option<String>,
    pub seed_error: Option<String>,
}

/// Validate a generated piece length for the selected output format.
pub fn validate_creation_piece_length(
    piece_length: u64,
    format: TorrentCreationFormat,
) -> Result<()> {
    if piece_length == 0 || piece_length > MAX_PIECE_LENGTH {
        return Err(CoreError::InvalidArgument(format!(
            "piece length must be between 1 and {MAX_PIECE_LENGTH} bytes"
        )));
    }
    if format.includes_v2() && (piece_length < V2_BLOCK_LENGTH || !piece_length.is_power_of_two()) {
        return Err(CoreError::InvalidArgument(format!(
            "BEP 52 piece length must be a power of two of at least {V2_BLOCK_LENGTH} bytes"
        )));
    }
    Ok(())
}

/// Validate a top-level torrent name.
pub fn validate_creation_name(name: &str) -> Result<()> {
    validate_component(name, "torrent name")
}

/// Validate one path component in a generated file path.
pub fn validate_creation_component(component: &str, context: &str) -> Result<()> {
    validate_component(component, context)
}

fn validate_component(value: &str, context: &str) -> Result<()> {
    if value.is_empty() || value == "." || value == ".." {
        return Err(CoreError::InvalidArgument(format!(
            "{context} must be a non-empty path component other than '.' or '..'"
        )));
    }
    if value.contains('/') || value.contains('\\') || value.contains('\0') {
        return Err(CoreError::InvalidArgument(format!(
            "{context} must not contain path separators or NUL"
        )));
    }
    Ok(())
}

/// Streaming hashes for one created torrent.
///
/// The daemon feeds bytes file by file. v1 SHA-1 pieces span file boundaries;
/// BEP 52 piece hashes, file roots, and piece layers reset at each file. The
/// hasher never allocates proportional to total source size.
pub struct CreationHasher {
    piece_length: u64,
    format: TorrentCreationFormat,
    v1_piece_hasher: sha1::Sha1,
    v1_piece_filled: u64,
    v1_pieces: Vec<[u8; 20]>,
    total_bytes: u64,
    file_open: bool,
    v2_block_hasher: sha2::Sha256,
    v2_block_filled: u64,
    v2_piece_blocks: Vec<V2InfoHash>,
    v2_piece_hashes: Vec<V2InfoHash>,
    v2_total_pieces: usize,
}

/// Per-file BEP 52 hashes returned at a file boundary.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CreationFileHashes {
    pub pieces_root: Option<V2InfoHash>,
    pub piece_layer: Vec<V2InfoHash>,
}

impl CreationHasher {
    pub fn new(piece_length: u64, format: TorrentCreationFormat) -> Result<Self> {
        validate_creation_piece_length(piece_length, format)?;
        Ok(Self {
            piece_length,
            format,
            v1_piece_hasher: sha1::Sha1::new(),
            v1_piece_filled: 0,
            v1_pieces: Vec::new(),
            total_bytes: 0,
            file_open: false,
            v2_block_hasher: <sha2::Sha256 as sha2::Digest>::new(),
            v2_block_filled: 0,
            v2_piece_blocks: Vec::new(),
            v2_piece_hashes: Vec::new(),
            v2_total_pieces: 0,
        })
    }

    pub fn begin_file(&mut self) -> Result<()> {
        if self.file_open {
            return Err(CoreError::Internal(
                "creation hasher file boundary is already open".into(),
            ));
        }
        self.file_open = true;
        self.v2_block_filled = 0;
        self.v2_piece_blocks.clear();
        self.v2_piece_hashes.clear();
        Ok(())
    }

    pub fn update(&mut self, bytes: &[u8]) -> Result<()> {
        if !self.file_open {
            return Err(CoreError::Internal(
                "creation hasher update outside a file boundary".into(),
            ));
        }
        self.total_bytes = self
            .total_bytes
            .checked_add(bytes.len() as u64)
            .ok_or_else(|| CoreError::InvalidArgument("source length exceeds u64".into()))?;
        if self.format.includes_v1() {
            use sha1::Digest;
            let mut v1_bytes = bytes;
            while !v1_bytes.is_empty() {
                let take = std::cmp::min(
                    v1_bytes.len() as u64,
                    self.piece_length.saturating_sub(self.v1_piece_filled),
                ) as usize;
                self.v1_piece_hasher.update(&v1_bytes[..take]);
                self.v1_piece_filled += take as u64;
                v1_bytes = &v1_bytes[take..];
                if self.v1_piece_filled == self.piece_length {
                    let digest = self.v1_piece_hasher.finalize_reset();
                    let mut hash = [0u8; 20];
                    hash.copy_from_slice(&digest);
                    self.v1_pieces.push(hash);
                    if self.v1_pieces.len() > MAX_TORRENT_PIECES {
                        return Err(CoreError::InvalidArgument(format!(
                            "source produces more than {MAX_TORRENT_PIECES} pieces"
                        )));
                    }
                    self.v1_piece_filled = 0;
                }
            }
        }
        if self.format.includes_v2() {
            use sha2::Digest;
            let piece_block_count = self.piece_length / V2_BLOCK_LENGTH;
            let mut v2_bytes = bytes;
            while !v2_bytes.is_empty() {
                let take = std::cmp::min(
                    v2_bytes.len() as u64,
                    V2_BLOCK_LENGTH.saturating_sub(self.v2_block_filled),
                ) as usize;
                self.v2_block_hasher.update(&v2_bytes[..take]);
                self.v2_block_filled += take as u64;
                v2_bytes = &v2_bytes[take..];
                if self.v2_block_filled == V2_BLOCK_LENGTH {
                    let digest = self.v2_block_hasher.finalize_reset();
                    let mut hash = [0u8; 32];
                    hash.copy_from_slice(&digest);
                    self.v2_piece_blocks.push(V2InfoHash::from_bytes(hash));
                    self.v2_block_filled = 0;
                    if self.v2_piece_blocks.len() as u64 == piece_block_count {
                        self.finish_v2_piece()?;
                    }
                }
            }
        }
        Ok(())
    }

    pub fn finish_file(&mut self) -> Result<CreationFileHashes> {
        if !self.file_open {
            return Err(CoreError::Internal(
                "creation hasher file boundary is not open".into(),
            ));
        }
        self.file_open = false;
        if !self.format.includes_v2() {
            return Ok(CreationFileHashes {
                pieces_root: None,
                piece_layer: Vec::new(),
            });
        }
        use sha2::Digest;
        if self.v2_block_filled > 0 {
            let digest = self.v2_block_hasher.finalize_reset();
            let mut hash = [0u8; 32];
            hash.copy_from_slice(&digest);
            self.v2_piece_blocks.push(V2InfoHash::from_bytes(hash));
            self.v2_block_filled = 0;
        }
        if !self.v2_piece_blocks.is_empty() {
            self.finish_v2_piece()?;
        }
        if self.v2_piece_hashes.is_empty() {
            return Ok(CreationFileHashes {
                pieces_root: None,
                piece_layer: Vec::new(),
            });
        }
        let (root, layer) = if self.v2_piece_hashes.len() == 1 {
            let root = self.v2_piece_hashes[0];
            self.v2_piece_hashes.clear();
            (root, Vec::new())
        } else {
            let root = crate::meta::v2_piece_layer_root(&self.v2_piece_hashes, self.piece_length)?;
            (root, std::mem::take(&mut self.v2_piece_hashes))
        };
        Ok(CreationFileHashes {
            pieces_root: Some(root),
            piece_layer: layer,
        })
    }

    fn finish_v2_piece(&mut self) -> Result<()> {
        self.v2_total_pieces = self.v2_total_pieces.saturating_add(1);
        if self.v2_total_pieces > MAX_TORRENT_PIECES {
            return Err(CoreError::InvalidArgument(format!(
                "source produces more than {MAX_TORRENT_PIECES} BEP 52 pieces"
            )));
        }
        let hash = crate::meta::v2_piece_layer_root(&self.v2_piece_blocks, V2_BLOCK_LENGTH)?;
        self.v2_piece_hashes.push(hash);
        self.v2_piece_blocks.clear();
        Ok(())
    }

    pub fn finish_torrent(mut self) -> Result<Vec<[u8; 20]>> {
        if self.file_open {
            return Err(CoreError::Internal(
                "creation hasher finished with an open file".into(),
            ));
        }
        if self.format.includes_v1() && self.v1_piece_filled > 0 {
            use sha1::Digest;
            let digest = self.v1_piece_hasher.finalize();
            let mut hash = [0u8; 20];
            hash.copy_from_slice(&digest);
            self.v1_pieces.push(hash);
        }
        if self.format.includes_v1() {
            let expected = self.total_bytes.div_ceil(self.piece_length);
            if self.v1_pieces.len() as u64 != expected {
                return Err(CoreError::InvalidArgument(format!(
                    "hashed {} v1 pieces; expected {expected}",
                    self.v1_pieces.len()
                )));
            }
        }
        Ok(self.v1_pieces)
    }
}

/// Build a complete `.torrent` document. The caller must still run
/// `meta::parse_torrent` over the result before publishing it.
pub fn build_torrent(spec: &TorrentCreationSpec) -> Result<Vec<u8>> {
    validate_creation_name(&spec.name)?;
    validate_creation_piece_length(spec.piece_length, spec.format)?;
    if spec.files.is_empty() {
        return Err(CoreError::InvalidArgument(
            "torrent creation requires at least one file".into(),
        ));
    }
    if spec.files.len() > MAX_TORRENT_FILES {
        return Err(CoreError::InvalidArgument(format!(
            "torrent creation supports at most {MAX_TORRENT_FILES} files"
        )));
    }
    let total_length = spec.files.iter().try_fold(0u64, |total, file| {
        total
            .checked_add(file.length)
            .ok_or_else(|| CoreError::InvalidArgument("total source length exceeds u64".into()))
    })?;
    if total_length == 0 {
        return Err(CoreError::InvalidArgument(
            "torrent creation requires non-empty source data".into(),
        ));
    }
    let expected_pieces = total_length.div_ceil(spec.piece_length);
    if expected_pieces > MAX_TORRENT_PIECES as u64 {
        return Err(CoreError::InvalidArgument(format!(
            "torrent would contain {expected_pieces} pieces; maximum is {MAX_TORRENT_PIECES}"
        )));
    }
    if spec.format.includes_v1() && spec.v1_pieces.len() as u64 != expected_pieces {
        return Err(CoreError::InvalidArgument(format!(
            "v1 piece count {} does not match expected {expected_pieces}",
            spec.v1_pieces.len()
        )));
    }
    if !spec.format.includes_v1() && !spec.v1_pieces.is_empty() {
        return Err(CoreError::InvalidArgument(
            "pure v2 creation must not carry v1 piece hashes".into(),
        ));
    }
    for file in &spec.files {
        if file.path.is_empty() || file.path[0] != spec.name {
            return Err(CoreError::InvalidArgument(
                "every generated file path must begin with the torrent name".into(),
            ));
        }
        for (index, component) in file.path.iter().enumerate() {
            validate_creation_component(component, &format!("file path component {}", index + 1))?;
        }
        if file.length == 0 {
            if file.pieces_root.is_some() || !file.piece_layer.is_empty() {
                return Err(CoreError::InvalidArgument(
                    "zero-length files must not carry BEP 52 hashes".into(),
                ));
            }
            continue;
        }
        if spec.format.includes_v2() {
            let root = file.pieces_root.ok_or_else(|| {
                CoreError::InvalidArgument(format!(
                    "non-empty BEP 52 file {} is missing its pieces root",
                    file.path.join("/")
                ))
            })?;
            if file.length > spec.piece_length {
                let expected = file.length.div_ceil(spec.piece_length);
                if file.piece_layer.len() as u64 != expected {
                    return Err(CoreError::InvalidArgument(format!(
                        "BEP 52 file {} has {} piece hashes; expected {expected}",
                        file.path.join("/"),
                        file.piece_layer.len()
                    )));
                }
                if crate::meta::v2_piece_layer_root(&file.piece_layer, spec.piece_length)? != root {
                    return Err(CoreError::InvalidArgument(format!(
                        "BEP 52 piece layer for {} does not match its pieces root",
                        file.path.join("/")
                    )));
                }
            } else if !file.piece_layer.is_empty() {
                return Err(CoreError::InvalidArgument(format!(
                    "BEP 52 file {} at or below piece length must not carry a piece layer",
                    file.path.join("/")
                )));
            }
        }
    }

    let mut out = Vec::new();
    out.push(b'd');
    if let Some(first) = spec
        .tracker_tiers
        .iter()
        .flat_map(|tier| tier.iter())
        .find(|url| !url.trim().is_empty())
    {
        write_bytes(&mut out, b"announce", first.as_bytes());
    }
    if spec.tracker_tiers.iter().any(|tier| !tier.is_empty()) {
        write_key(&mut out, b"announce-list");
        out.push(b'l');
        for tier in spec.tracker_tiers.iter().filter(|tier| !tier.is_empty()) {
            out.push(b'l');
            for url in tier {
                if !url.trim().is_empty() {
                    write_str(&mut out, url.as_bytes());
                }
            }
            out.push(b'e');
        }
        out.push(b'e');
    }

    write_key(&mut out, b"info");
    out.extend_from_slice(&build_info(spec)?);

    if spec.format.includes_v2() {
        let mut layers: BTreeMap<[u8; 32], Vec<u8>> = BTreeMap::new();
        for file in &spec.files {
            if file.piece_layer.is_empty() {
                continue;
            }
            let root = file
                .pieces_root
                .ok_or_else(|| CoreError::InvalidArgument("missing BEP 52 root".into()))?;
            let mut bytes = Vec::with_capacity(file.piece_layer.len() * 32);
            for hash in &file.piece_layer {
                bytes.extend_from_slice(hash.as_bytes());
            }
            match layers.get(root.as_bytes()) {
                Some(existing) if existing != &bytes => {
                    return Err(CoreError::InvalidArgument(
                        "two different BEP 52 piece layers share one pieces root".into(),
                    ));
                }
                Some(_) => {}
                None => {
                    layers.insert(*root.as_bytes(), bytes);
                }
            }
        }
        write_key(&mut out, b"piece layers");
        out.push(b'd');
        for (root, bytes) in layers {
            write_str(&mut out, &root);
            write_str(&mut out, &bytes);
        }
        out.push(b'e');
    }

    if !spec.webseeds.is_empty() {
        write_key(&mut out, b"url-list");
        if spec.webseeds.len() == 1 {
            write_str(&mut out, spec.webseeds[0].as_bytes());
        } else {
            out.push(b'l');
            for url in &spec.webseeds {
                write_str(&mut out, url.as_bytes());
            }
            out.push(b'e');
        }
    }
    out.push(b'e');
    Ok(out)
}

fn build_info(spec: &TorrentCreationSpec) -> Result<Vec<u8>> {
    let mut info = Vec::new();
    info.push(b'd');
    if spec.format.includes_v2() {
        write_key(&mut info, b"file tree");
        write_file_tree(&mut info, &spec.files);
    }
    if spec.format.includes_v1() {
        if spec.is_multi_file {
            write_key(&mut info, b"files");
            info.push(b'l');
            for file in &spec.files {
                info.push(b'd');
                write_key(&mut info, b"length");
                write_int(&mut info, file.length);
                write_key(&mut info, b"path");
                info.push(b'l');
                for component in file.path.iter().skip(1) {
                    write_str(&mut info, component.as_bytes());
                }
                info.push(b'e');
                info.push(b'e');
            }
            info.push(b'e');
        } else {
            write_key(&mut info, b"length");
            write_int(&mut info, spec.files[0].length);
        }
    }
    if spec.format.includes_v2() {
        write_key(&mut info, b"meta version");
        write_int(&mut info, 2);
    }
    write_key(&mut info, b"name");
    write_str(&mut info, spec.name.as_bytes());
    write_key(&mut info, b"piece length");
    write_int(&mut info, spec.piece_length);
    if spec.format.includes_v1() {
        write_key(&mut info, b"pieces");
        let mut pieces = Vec::with_capacity(spec.v1_pieces.len() * 20);
        for piece in &spec.v1_pieces {
            pieces.extend_from_slice(piece);
        }
        write_str(&mut info, &pieces);
    }
    if spec.private {
        write_key(&mut info, b"private");
        write_int(&mut info, 1);
    }
    info.push(b'e');
    Ok(info)
}

#[derive(Default)]
struct TreeNode {
    children: BTreeMap<Vec<u8>, TreeNode>,
    file: Option<(u64, Option<V2InfoHash>)>,
}

fn write_file_tree(out: &mut Vec<u8>, files: &[CreationFile]) {
    let mut root = TreeNode::default();
    for file in files {
        let mut node = &mut root;
        for component in &file.path {
            node = node
                .children
                .entry(component.as_bytes().to_vec())
                .or_default();
        }
        node.file = Some((file.length, file.pieces_root));
    }
    write_tree_node(out, &root);
}

fn write_tree_node(out: &mut Vec<u8>, node: &TreeNode) {
    out.push(b'd');
    for (component, child) in &node.children {
        write_str(out, component);
        write_tree_child(out, child);
    }
    out.push(b'e');
}

fn write_tree_child(out: &mut Vec<u8>, node: &TreeNode) {
    out.push(b'd');
    if let Some((length, root)) = node.file {
        write_str(out, b"");
        out.push(b'd');
        write_key(out, b"length");
        write_int(out, length);
        if let Some(root) = root {
            write_key(out, b"pieces root");
            write_str(out, root.as_bytes());
        }
        out.push(b'e');
    }
    for (component, child) in &node.children {
        write_str(out, component);
        write_tree_child(out, child);
    }
    out.push(b'e');
}

fn write_key(out: &mut Vec<u8>, key: &[u8]) {
    write_str(out, key);
}

fn write_bytes(out: &mut Vec<u8>, key: &[u8], value: &[u8]) {
    write_key(out, key);
    write_str(out, value);
}

fn write_str(out: &mut Vec<u8>, value: &[u8]) {
    out.extend_from_slice(value.len().to_string().as_bytes());
    out.push(b':');
    out.extend_from_slice(value);
}

fn write_int(out: &mut Vec<u8>, value: u64) {
    out.push(b'i');
    out.extend_from_slice(value.to_string().as_bytes());
    out.push(b'e');
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::meta::{parse_torrent, v2_piece_layer_root};

    fn v1_pieces(content: &[u8], piece_length: u64) -> Vec<[u8; 20]> {
        use sha1::{Digest, Sha1};
        content
            .chunks(piece_length as usize)
            .map(|chunk| {
                let digest = Sha1::digest(chunk);
                let mut hash = [0u8; 20];
                hash.copy_from_slice(&digest);
                hash
            })
            .collect()
    }

    fn v2_file(content: &[u8], piece_length: u64) -> (V2InfoHash, Vec<V2InfoHash>) {
        use sha2::{Digest, Sha256};
        let mut piece_layer = Vec::new();
        for piece in content.chunks(piece_length as usize) {
            let mut blocks = Vec::new();
            for block in piece.chunks(V2_BLOCK_LENGTH as usize) {
                let digest = Sha256::digest(block);
                let mut hash = [0u8; 32];
                hash.copy_from_slice(&digest);
                blocks.push(V2InfoHash::from_bytes(hash));
            }
            piece_layer.push(v2_piece_layer_root(&blocks, V2_BLOCK_LENGTH).unwrap());
        }
        let root = if content.len() as u64 <= piece_length {
            piece_layer[0]
        } else {
            v2_piece_layer_root(&piece_layer, piece_length).unwrap()
        };
        (
            root,
            if content.len() as u64 <= piece_length {
                Vec::new()
            } else {
                piece_layer
            },
        )
    }

    fn single_spec(
        content: &[u8],
        piece_length: u64,
        format: TorrentCreationFormat,
    ) -> TorrentCreationSpec {
        let (root, layer) = if format.includes_v2() {
            v2_file(content, piece_length)
        } else {
            (V2InfoHash::ZERO, Vec::new())
        };
        TorrentCreationSpec {
            name: "created.bin".into(),
            piece_length,
            format,
            is_multi_file: false,
            files: vec![CreationFile {
                path: vec!["created.bin".into()],
                length: content.len() as u64,
                pieces_root: format.includes_v2().then_some(root),
                piece_layer: layer,
            }],
            v1_pieces: if format.includes_v1() {
                v1_pieces(content, piece_length)
            } else {
                Vec::new()
            },
            tracker_tiers: vec![vec!["https://tracker.example/announce".into()]],
            webseeds: vec!["https://seed.example/files/".into()],
            private: true,
        }
    }

    #[test]
    fn v1_creation_round_trips_with_partial_piece() {
        let content = b"generated creation payload that ends in a partial piece";
        let spec = single_spec(content, 16, TorrentCreationFormat::V1);
        let bytes = build_torrent(&spec).unwrap();
        let parsed = parse_torrent(&bytes).unwrap();
        assert_eq!(
            parsed.identity,
            crate::hash::TorrentIdentity::v1(parsed.info_hash)
        );
        assert_eq!(parsed.pieces.len(), content.len().div_ceil(16));
        assert_eq!(parsed.total_length, content.len() as u64);
        assert!(parsed.private);
        assert_eq!(parsed.announce_list.len(), 1);
        assert_eq!(parsed.webseeds, vec!["https://seed.example/files/"]);
        assert_eq!(parsed.raw_info, Some(build_info(&spec).unwrap()));
        assert_eq!(&parsed.pieces[0], &v1_pieces(content, 16)[0]);
    }

    #[test]
    fn v2_creation_round_trips_multi_file_piece_layers() {
        let first = vec![b'A'; 40 * 1024];
        let second = vec![b'B'; 20 * 1024];
        let piece_length = V2_BLOCK_LENGTH;
        let (first_root, first_layer) = v2_file(&first, piece_length);
        let (second_root, second_layer) = v2_file(&second, piece_length);
        let spec = TorrentCreationSpec {
            name: "bundle".into(),
            piece_length,
            format: TorrentCreationFormat::V2,
            is_multi_file: true,
            files: vec![
                CreationFile {
                    path: vec!["bundle".into(), "first.bin".into()],
                    length: first.len() as u64,
                    pieces_root: Some(first_root),
                    piece_layer: first_layer,
                },
                CreationFile {
                    path: vec!["bundle".into(), "nested".into(), "second.bin".into()],
                    length: second.len() as u64,
                    pieces_root: Some(second_root),
                    piece_layer: second_layer,
                },
            ],
            v1_pieces: Vec::new(),
            tracker_tiers: Vec::new(),
            webseeds: Vec::new(),
            private: false,
        };
        let bytes = build_torrent(&spec).unwrap();
        let parsed = parse_torrent(&bytes).unwrap();
        assert!(matches!(
            parsed.identity,
            crate::hash::TorrentIdentity::V2 { .. }
        ));
        assert_eq!(parsed.files.len(), 2);
        assert_eq!(parsed.total_length, (first.len() + second.len()) as u64);
        assert_eq!(parsed.v2.as_ref().unwrap().piece_layers.len(), 2);
        assert!(parsed.announce.is_none());
        assert!(parsed.announce_list.is_empty());
        assert!(parsed.webseeds.is_empty());
    }

    #[test]
    fn hybrid_creation_round_trips_one_identity() {
        let content = b"hybrid generated payload with enough bytes for multiple pieces".to_vec();
        let piece_length = V2_BLOCK_LENGTH;
        let spec = single_spec(&content, piece_length, TorrentCreationFormat::Hybrid);
        let bytes = build_torrent(&spec).unwrap();
        let parsed = parse_torrent(&bytes).unwrap();
        assert!(matches!(
            parsed.identity,
            crate::hash::TorrentIdentity::Hybrid { .. }
        ));
        assert_eq!(parsed.files.len(), 1);
        assert_eq!(parsed.v2.as_ref().unwrap().files.len(), 1);
        assert_eq!(spec.v1_pieces.len(), parsed.pieces.len());
    }

    #[test]
    fn invalid_creation_inputs_are_rejected() {
        let content = b"valid payload";
        let mut spec = single_spec(content, V2_BLOCK_LENGTH, TorrentCreationFormat::V2);
        spec.files[0].piece_layer.push(V2InfoHash::ZERO);
        assert!(build_torrent(&spec).is_err());
        assert!(validate_creation_piece_length(12, TorrentCreationFormat::V2).is_err());
        assert!(validate_creation_name("bad/name").is_err());
        assert!(validate_creation_name("..").is_err());
    }
}
